function extractCity(raw) {
  if (!raw) return null;
  const text = String(raw).trim();
  if (!text) return null;
  const STATE_NAMES = ['alabama','alaska','arizona','arkansas','california','colorado','connecticut','delaware','florida','georgia','hawaii','idaho','illinois','indiana','iowa','kansas','kentucky','louisiana','maine','maryland','massachusetts','michigan','minnesota','mississippi','missouri','montana','nebraska','nevada','new hampshire','new jersey','new mexico','new york','north carolina','north dakota','ohio','oklahoma','oregon','pennsylvania','rhode island','south carolina','south dakota','tennessee','texas','utah','vermont','virginia','washington','west virginia','wisconsin','wyoming','alberta','british columbia','manitoba','new brunswick','newfoundland and labrador','nova scotia','ontario','prince edward island','quebec','saskatchewan','northwest territories','nunavut','yukon'];
  const parts = text.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
  if (parts.length <= 1) return parts[0] || null;
  const last = parts[parts.length - 1];
  const lastLower = last.toLowerCase();
  const looksLikeStateOrZip = /^[A-Za-z]{2}(\s+\d{5}(-\d{4})?)?$/.test(last) || /^\d{5}(-\d{4})?$/.test(last) || /^[A-Za-z]\d[A-Za-z]\s*\d[A-Za-z]\d$/.test(last) || STATE_NAMES.indexOf(lastLower) !== -1;
  if (looksLikeStateOrZip && parts.length >= 2) {
    return parts[parts.length - 2];
  }
  return last;
}

function toEngineDateTime(raw) {
  if (!raw) return null;
  const text = String(raw).trim();
  if (!text) return null;
  // The rate engine's date parser rejects a leading weekday name and the
  // word 'at' between date and time (e.g. 'Tuesday, August 25, 2026 at
  // 10:00 AM'). Strip those, then normalize to an unambiguous format.
  const cleaned = text.replace(/^[A-Za-z]+day,?\s*/i, '').replace(/\s+at\s+/i, ' ').trim();
  const parsed = new Date(cleaned);
  if (isNaN(parsed.getTime())) {
    return cleaned;
  }
  const yyyy = parsed.getFullYear();
  const mm = String(parsed.getMonth() + 1).padStart(2, '0');
  const dd = String(parsed.getDate()).padStart(2, '0');
  const hh = String(parsed.getHours()).padStart(2, '0');
  const min = String(parsed.getMinutes()).padStart(2, '0');
  const hasTime = /\d{1,2}:\d{2}/.test(cleaned);
  return hasTime ? (yyyy + '-' + mm + '-' + dd + 'T' + hh + ':' + min + ':00') : (yyyy + '-' + mm + '-' + dd);
}

// If the caller already manually confirmed a specific vehicle class earlier
// in this call (via N07 Capacity Mismatch), never recompute or overwrite it -
// a later correction (address, time, etc.) re-running this node must not
// silently discard that choice and fall back to a passenger-count guess.
if (dv.vehicle_manually_confirmed === 'true' && dv.vehicle_class) {
  const legDirection = dv.leg_direction || '';
  const rate_trip_type = legDirection === 'charter' ? 'hourly' : 'airport';
  let origin_city = null;
  if (legDirection === 'arrival') {
    origin_city = extractCity(dv.dropoff_or_duration);
  } else if (legDirection === 'departure') {
    origin_city = extractCity(dv.pickup_location);
  } else if (legDirection === 'charter') {
    origin_city = extractCity(dv.pickup_location);
  }
  let rate_pickup_at = null;
  if (legDirection === 'charter') {
    rate_pickup_at = toEngineDateTime(dv.pickup_datetime);
  } else if (legDirection === 'arrival') {
    rate_pickup_at = toEngineDateTime(dv.flight_date);
  } else if (legDirection === 'departure') {
    rate_pickup_at = toEngineDateTime((dv.flight_date && dv.pickup_time) ? (dv.flight_date + ' ' + dv.pickup_time) : dv.flight_date);
  }
  return {
    vehicle_class: dv.vehicle_class,
    vehicle_class_label: dv.vehicle_class_label || dv.vehicle_class,
    vehicle_root: dv.vehicle_root || dv.vehicle_class,
    oversized: false,
    oversized_reason: null,
    larger_class_name: null,
    rate_trip_type,
    origin_city,
    rate_pickup_at
  };
}

const pax = Number(dv.passenger_count);
const stops = Number(dv.stops_count);
const stretchExplicit = dv.stretch_requested === 'true';
const wheelchairLift = dv.wheelchair_lift_needed === 'true';
const oversizedItem = dv.oversized_item_needed === 'true';

let vehicle_class = null;
let vehicle_class_label = null;
let oversized = false;
let oversized_reason = null;
let larger_class_name = null;

// Escalate to dispatch only when the engine genuinely cannot price this:
// equipment the engine has no field for yet, too many stops, or a group
// bigger than any single vehicle. Everything else self-quotes - the
// engine's own capacity_ok / suggested_vehicle (see N07 Capacity Check)
// is the authority on vehicle fit, not a client-side matrix.
if (wheelchairLift || oversizedItem) {
  oversized = true;
  oversized_reason = 'equipment';
} else if (Number.isFinite(stops) && stops > 3) {
  oversized = true;
  oversized_reason = 'stops';
} else if (Number.isFinite(pax) && pax > 56) {
  oversized = true;
  oversized_reason = 'passengers';
  larger_class_name = 'motorcoach';
} else if (stretchExplicit) {
  vehicle_class = 'stretch';
  vehicle_class_label = 'Stretch Limousine';
} else if (Number.isFinite(pax) && pax <= 3) {
  vehicle_class = 'sedan';
  vehicle_class_label = 'Executive Sedan';
} else if (Number.isFinite(pax) && pax <= 6) {
  vehicle_class = 'suv';
  vehicle_class_label = 'Executive SUV';
} else {
  // 7 to 56 passengers (or passenger count not yet finalized): start
  // with the Sprinter as a reasonable guess. N07 Capacity Check reads
  // capacity_ok / suggested_vehicle from the engine and N07 Capacity
  // Mismatch corrects the vehicle and re-quotes automatically.
  vehicle_class = 'van_sprinter';
  vehicle_class_label = 'Sprinter Van';
}

// vehicle_root is a normalized root word used ONLY to compare vehicle_class
// against the rate engine's suggested_vehicle (N07 Capacity Check), since
// the engine's suggested_vehicle uses a different, branded key convention
// for the same class (e.g. 'sedan' here vs 'sedan_exec' from the engine;
// 'van_sprinter' here vs 'sprinter_exec_14' from the engine). Comparing
// vehicle_class directly against suggested_vehicle by exact string always
// mismatches even when there's no real upgrade, so N07 instead checks
// whether suggested_vehicle CONTAINS this root - a true mismatch (e.g. a
// bag-count-driven upgrade) still gets caught because the engine's
// suggested_vehicle for the larger class won't contain this root either.
let vehicle_root = vehicle_class;
if (vehicle_class === 'van_sprinter') {
  vehicle_root = 'sprinter';
}

const legDirection = dv.leg_direction || '';
const rate_trip_type = legDirection === 'charter' ? 'hourly' : 'airport';

// origin_city is the ZONE-LOOKUP KEY - it must be the bare city name only,
// never a full street address, or the engine's exact-zone lane misses the
// row and silently falls through to national mileage pricing. The full
// address is still sent separately as pickup_address on commit - this
// field is for rate lookup only. Never restrict the city itself to a
// fixed list, so trips outside Wisconsin still resolve correctly.
let origin_city = null;
if (legDirection === 'arrival') {
  origin_city = extractCity(dv.dropoff_or_duration);
} else if (legDirection === 'departure') {
  origin_city = extractCity(dv.pickup_location);
} else if (legDirection === 'charter') {
  origin_city = extractCity(dv.pickup_location);
}

let rate_pickup_at = null;
if (legDirection === 'charter') {
  rate_pickup_at = toEngineDateTime(dv.pickup_datetime);
} else if (legDirection === 'arrival') {
  rate_pickup_at = toEngineDateTime(dv.flight_date);
} else if (legDirection === 'departure') {
  rate_pickup_at = toEngineDateTime((dv.flight_date && dv.pickup_time) ? (dv.flight_date + ' ' + dv.pickup_time) : dv.flight_date);
}

return { vehicle_class, vehicle_class_label, vehicle_root, oversized, oversized_reason, larger_class_name, rate_trip_type, origin_city, rate_pickup_at };

const prevCount = Number(dv.missing_slot_retry_count) || 0;
const count = prevCount + 1;
return { missing_slot_retry_count: count };

const required = {
  origin_city: dv.origin_city,
  rate_pickup_at: dv.rate_pickup_at,
  leg_1_summary: dv.leg_1_summary,
  vehicle_class: dv.vehicle_class,
  passenger_count: dv.passenger_count,
  rate_trip_type: dv.rate_trip_type
};
let rate_input_valid = true;
for (const key in required) {
  const val = required[key];
  if (val === undefined || val === null || val === '' || String(val).includes('{{') || String(val).includes('}}')) {
    rate_input_valid = false;
    break;
  }
}
return { rate_input_valid };
